D=$(mktemp -d) && cp src/runtime.zig $D/rt.zig && cd $D && echo  | base64 -d > h.zig && { echo 'const std = @import("std");'; echo 'pub var tripped: bool = false;'; s=$(grep -n '^noinline fn laneOverflow' rt.zig | cut -d: -f1); e=$(grep -n '^pub inline fn vecNeg' rt.zig | cut -d: -f1); sed -n "${s},$((e+5))p" rt.zig | sed 's/^noinline fn laneOverflow() noreturn {/noinline fn laneOverflow() void {/; s/    panic.integerOverflow();/    tripped = true;/; s/^inline fn/pub inline fn/'; } > helpers.zig && tail -3 helpers.zig && uname -m && for m in ReleaseSafe Debug; do zig build-exe h.zig -lc -O $m -femit-bin=h_$m -j2 && ./h_$m 2>&1 | tail -20; echo RC_$m=${PIPESTATUS[0]}; done; cd /; rm -rf $D
